@export('retry') def retry ( max_tries = 3 ):

    def decorator ( f ):
        @wraps ( f )
        def wrapper ( * args , ** kwargs ):
            # Loop to retry the operation up to the specified number of times
            for _ in range ( max_tries ):
                try :
                    return f ( * args , ** kwargs )
                except Exception :
                    pass
        return wrapper
    return decorator

