# Global dictionary storing query parameter counters for tracking by key
counters = {}

@app.get("/api/counter")
async def count(request: Request):
    # Extract the id parameter directly from the query string using Request object
    id_value = request.query_params.get("id")

    # Mark parameters starting with '91' as invalid for filtering purposes
    is_invalid = id_value.startswith("91")

    # Track request frequency using simple integer counter per parameter key
    if id_value in counters:
        counters[id_value] += 1
    else:
        counters[id_value] = 1

    # Package response details into a structured dictionary format
    data = {
        "id": id_value,
        "invalid": is_invalid,
        "count": counters[id_value],
    }

    return JSONResponse(data)

