from collections import defaultdict, OrderedDict

def longest_common_substring_dp(str1, str2):
    # Track maximum substring length and its position in first string
    max_len = 0
    max_start = -1

    # Build的动态规划表记录当前位置的最长公共前缀
    dp = [[0] * (len(str2) + 1) for _ in range(len(str1) + 1)]

    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                # 如果字符匹配，则延续前一位置的最长公共前缀长度
                dp[i][j] = dp[i - 1][j - 1] + 1
                # 在全局范围内追踪最长子串
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    max_start = i - max_len
            else:
                # 失配时重置为0，中断子串延续
                dp[i][j] = 0

    # 使用DP表直接提取完整的最长公共子串
    return str1[max_start: max_start + max_len]

def longest_common_substring_all(str1, str2):
    # 使用 defaultdict 创建带列表的字典，存储每个长度对应的所有子串数量
    substrings = defaultdict(list)
    # 遍历 str1 的所有子串，并计数其在 str2 中出现的次数
    for i in range(len(str1)):
        s = ''
        for j in range(i, len(str1)):
            s += str1[j]
            # 在 defaultdict 中统计每个子串的出现频率
            substrings[len(s)].append(s)

    longest_len = 0
    longest_subs = []
    # 按长度降序遍历，找出最长的公共子串
    for length, subs in sorted(substrings.items(), key=lambda x: -x[0]):
        # 检查该长度的所有子串是否在另一个字符串中出现
        for s in set(subs):
            # 遇到第一个公共子串即为最长，加入结果并继续收集相同长度的其他可能
            if s in str2:
                longest_len = length
                longest_subs.append(s)

        if longest_len > 0:
            # 将结果去重并按字典序排序输出
            return sorted(set(longest_subs), key=lambda s: (s, str1.index(s)))

