    this.patient = Promise.all([
      this.getDemographics(),
      this.getDiagnoses(),
      this.getMedications()
    ]).then(([demographics, diagnoses, medications]) => {
      // Build a comprehensive profile object by combining fetched data
      return {
        demographics: demographics,
        diagnoses: diagnoses,
        medications: medications
      }
    });
  }

  getDemographics() {
    return Fluid.get("/patient/demographics");
  }

  getDiagnoses() {
    return Fluid.get("/patient/diagnoses");
  }

  getMedications() {
    return Fluid.get("/patient/medications");
  }
}

